#!/usr/bin/env python3
"""
place_frontback.py  —  Put the final dissertation abstract, Chapter 1 and Chapter 5 into the book
====================================================================================================
Run from the dissertation repo root:   python3 tools/place_frontback.py [--check]

What it does
    index.qmd                         replaces the text between \\begin{ucrabstract} and \\end{ucrabstract}
    Chapter_1_General_Introduction.qmd   whole file replaced (scaffolding removed)
    Chapter_5_General_Conclusion.qmd     whole file replaced (scaffolding removed)

Citation keys in the texts are already mapped to the keys in references.bib.
Safety: everything is checked in memory first; on any failure nothing is written.
Re-running is harmless (same output). --check verifies without writing.
"""
import os, re, sys

ROOT = os.getcwd()
ABSTRACT = 'Many everyday tasks require a perceptual or memory judgment while the body is working, yet it is unclear whether physical effort and task difficulty compete for shared processing resources, and whether their effects change with age. This dissertation tested how concurrent physical effort, an isometric handgrip held at 5% or 40% of maximum voluntary contraction, and task difficulty affect performance, decision processes, and pupil size. Chapter 2 tested 38 younger adults on a visual working-memory task and auditory and visual discrimination tasks. Harder trials were less accurate in every task and slower in both discrimination tasks, high physical effort slowed responses in the visual discrimination task and enlarged the pupil response in every task, and task difficulty and physical effort did not interact on any measure. Chapters 3 and 4 tested older adults on the two discrimination tasks in an MRI scanner. In Chapter 3, mixed-effects models of the psychometric function showed that high physical effort lowered the probability of reporting a difference without reducing sensitivity. The reduction was slightly larger for the smallest differences, and on trials with identical stimuli it was similar in size but uncertain on its own. In Chapter 4, a hierarchical Bayesian drift-diffusion model of choices and response times located this effect in a small shift of the drift criterion toward "same" responses, with little change in evidence quality, response caution, or the starting point. In older adults, physical effort changed pupil size only weakly, and no pupil measure taken before the decision accounted for the behavioral effects. Together, the studies offer little support for a single limited-capacity resource shared by physical effort and task difficulty at these force levels. In older adults, physical effort instead changed mainly how readily a difference was reported, a shift in decision policy rather than a loss of perceptual sensitivity. Because the younger and older samples differed in setting, stimuli, and measures, these findings do not by themselves establish an age difference. They motivate direct age comparisons, more levels of physical effort, and designs that separate the decision criterion from the response mapping.\n'
CH1 = "# General Introduction {#sec-general-introduction}\n\n## The problem\n\nMany everyday tasks combine a judgment with physical work. A driver gripping the steering wheel judges whether a gap in traffic is large enough, a person carrying groceries reads a price label, and a worker holding a tool listens for an alarm. Older adults meet such combinations often, and combining demands costs them more than it costs younger adults [@Lindenberger2000-aw; @Verhaeghen2003-ft]. Research on these costs in aging has mostly paired a cognitive task with walking [@Hausdorff2008-st; @Plummer-D-Amato2012-ss], even though many daily demands involve holding a steady force rather than moving. The few studies that held a force while manipulating task difficulty have examined working memory [@Azer2023-ft; @Park2021-rs], and studies of handgrip and cognition more often test performance after a period of exercise than during it [@Brown2015-zu; @Washio2021-kg]. It is therefore unclear whether physical effort and task difficulty draw on a common pool of resources, whether physical effort changes a judgment itself or only how it is reported, and whether the answer differs with age.\n\nThis dissertation addresses these questions with one manipulation used throughout: an isometric handgrip held at 5% or 40% of maximum voluntary contraction (MVC) while participants made memory and perceptual judgments of varying task difficulty, with pupil size recorded on every trial. The three empirical chapters move from asking whether the two demands interact in younger adults (Chapter 2) to asking how physical effort changes the judgment in older adults (Chapters 3 and 4).\n\n## Theoretical background\n\nTask difficulty is the cost that a judgment imposes through its own demands, such as more items to remember or a smaller difference to detect, and it appears as lower accuracy and slower responses [@Westbrook2015-gy]. Physical effort is the demand of producing force. An isometric handgrip held at a fixed proportion of MVC makes that demand precise and repeatable, raises heart rate and blood pressure [@Lind1967-tf], and engages the noradrenergic system [@Mather2020-ze]. Because the hand does not move, it is also compatible with eye tracking and brain imaging. People treat both demands as costs: given the choice, they avoid cognitive and physical effort alike, and the two costs are valued through partly shared neural mechanisms [@Chong2017-fx].\n\nThe few studies that combined the two demands concurrently disagree. In younger adults performing visual search, a 40% MVC grip sped responses but enlarged the cost of a distractor, an interaction between task difficulty and physical effort [@Park2021-rs]. With a 30% MVC grip, younger adults showed no effect of physical effort, whereas older adults' working-memory accuracy fell when distractors were present [@Azer2023-ft]. These results raise two questions that this dissertation takes up: whether an interaction between task difficulty and physical effort extends beyond visual working memory to perceptual judgments, and whether older adults are more susceptible to it.\n\nThree accounts make different predictions about combining the demands. A capacity account holds that concurrent demands compete for a single limited pool of processing resources [@Kahneman1973-jw]. If task difficulty and physical effort draw on that pool, the cost of physical effort should grow with task difficulty, producing an interaction. The account also predicts larger costs in older adults, whose processing resources are reduced [@Salthouse1991-vr] and who are less able to suppress task-irrelevant information [@Gazzaley2005-ib]. Multiple-resource accounts hold instead that different kinds of processing draw on partly separate resources, so that two demands interfere only to the extent that they share one [@Navon1979-jk; @Wickens2008-pj]. If producing force and comparing two stimuli draw on different resources, their effects should add without interacting. Adaptive gain theory offers a third view, in which performance depends on noradrenergic arousal and is best at an intermediate level [@Aston-Jones2005-dg]. If both demands raise arousal, combining them could push performance past that optimum, and because aging may shift the optimum to lower levels [@Mather2016-bx], a grip that is harmless for younger adults could be costly for older adults. The task difficulty × physical effort interaction is therefore the central test in every chapter, and its presence or absence in each age group distinguishes the accounts.\n\nAccuracy and response time show that performance changes, but not which part of the judgment changes. Signal detection theory separates sensitivity, how well two stimuli are discriminated, from the criterion, how much evidence is required before a difference is reported [@macmillan2005detection; @prins2016psychophysics]. Physical effort could lower sensitivity by making the evidence noisier, or it could shift the criterion, which would change how often a difference is reported even when there is none. The drift-diffusion model extends this distinction to response times [@Ratcliff2008-fj]. It describes a two-choice decision as evidence accumulating at a rate set by its quality until it reaches one of two boundaries. The model separates evidence quality from the distance between the boundaries, a measure of response caution, and from the starting point, a bias set before the stimulus appears. The drift criterion, the reference against which evidence counts as favoring one response or the other, is the diffusion-model counterpart of the criterion in signal detection theory. These distinctions matter in aging. Older adults typically show wider boundaries and longer non-decision times than younger adults, whereas evidence quality is often preserved on simple perceptual tasks [@ratcliff2001aging; @Theisen2021-fn], and older adults set their boundaries more conservatively than would maximize their reward rate [@Starns2010-iu]. Physical effort could therefore act on how older adults use the evidence rather than on the evidence itself, a possibility that accuracy alone cannot distinguish from a loss of capacity.\n\nPupil size offers one physiological measure that responds to both demands: it increases with task difficulty [@Beatty1982-wg; @Van_der_Wel2018-ko] and with physical effort [@Zenon2014-ze]. In adaptive gain theory, pupil size tracks activity of the locus coeruleus–noradrenaline system [@Aston-Jones2005-dg; @Joshi2016-zb], so the pupil offers a way to test whether the behavioral effects of physical effort run through that system. If the two demands share a pupil-linked resource, their effects on the pupil should interact, and pupil size should track the behavioral effects of physical effort. Two qualifications apply. Pupil size also covaries with activity outside the locus coeruleus [@Joshi2016-zb], and in older adults the pupil is smaller and its range of dilation narrower [@Winn1994-pi; @Piquado2010-eu], while the locus coeruleus is among the structures most vulnerable to aging [@Mather2016-bx].\n\n## The present research\n\nThe dissertation had three aims. The first was to test whether task difficulty and physical effort interact in younger adults across working memory and perceptual discrimination, and whether pupil size reflects both demands. The second was to test, in older adults, whether physical effort changes perceptual sensitivity or the criterion for reporting a difference. The third was to identify which decision process carries the effect of physical effort in older adults, and whether pupil size measured before or during the decision accounts for it.\n\nAll three studies used the same handgrip levels and crossed physical effort with task difficulty. The 5% level required holding the grip with a minimal force, and the 40% level was chosen because it produced an interaction with task difficulty in younger adults [@Park2021-rs], whereas 30% did not [@Azer2023-ft], and because it is a demand that could exceed older adults' optimal level of arousal. The younger adults in Chapter 2 were tested in a laboratory on three tasks. The older adults in Chapters 3 and 4 were a single cohort tested in an MRI scanner on the two discrimination tasks, with stimulus differences and trial timing adapted to that setting. Choices and confidence in that cohort were also analyzed by @sun2026handgrip. Because the younger and older samples differed in setting, stimuli, and measures, the dissertation compares the age groups across studies rather than testing age differences directly.\n\n## Overview of chapters\n\nChapter 2, published as @Dastgheib2026-crpi, tested 38 younger adults on a visual working-memory task and auditory and visual discrimination tasks while they held the grip at low or high physical effort. It asks whether task difficulty and physical effort interact on accuracy, response time, and the pupil response, and whether the behavioral and pupil effects of the two demands are related across individuals.\n\nChapter 3 turns to older adults performing the auditory and visual discrimination tasks. Using mixed-effects models of the psychometric function across all trials, it asks whether high physical effort lowers sensitivity, shifts the criterion for reporting a difference, or imposes a cost that grows with task difficulty, and whether pupil size before and after the stimulus to be judged tracks the judgment.\n\nChapter 4 analyzes the choices and response times of the same older adults with a hierarchical Bayesian drift-diffusion model. It asks whether physical effort changes evidence quality, response caution, the starting point, or the drift criterion, and whether pupil measures taken before and during the decision predict those decision processes.\n\nChapter 5 summarizes the findings, integrates them across the three studies, and considers their implications, limitations, and the studies they motivate.\n"
CH5 = '# General Conclusion {#sec-general-conclusion}\n\nThis dissertation asked whether concurrent physical effort and task difficulty compete for shared processing resources, how physical effort changes perceptual judgments in older adults, and whether pupil size accounts for these effects. This chapter summarizes the findings of each study, considers what the three studies show together, and sets out the implications, the limitations that cut across chapters, and the studies the findings motivate.\n\n## Summary of principal findings\n\nIn Chapter 2, 38 younger adults performed a visual working-memory task and auditory and visual discrimination tasks while holding a handgrip at 5% or 40% of MVC. Harder trials were less accurate in every task and slower in both discrimination tasks, and high physical effort slowed responses in the visual discrimination task only. High physical effort enlarged the pupil response across the trial in all three tasks, whereas task difficulty changed only an exploratory early pupil measure, in the auditory task. Task difficulty and physical effort did not interact on any behavioral or pupil measure, and equivalence tests on the behavioral measures rejected interactions as large as the one previously reported with the same handgrip levels [@Park2021-rs]. The behavioral and pupil effects of the two demands were not correlated across participants.\n\nIn Chapter 3, older adults performed the auditory and visual discrimination tasks in an MRI scanner. In a mixed-effects model of all trials, high physical effort lowered the probability of reporting "different" at the average stimulus difference (*b* = −0.10, 95% CI [−0.15, −0.04]), and the psychometric function did not become shallower. The reduction was slightly larger for the smallest differences (offset × physical effort, *b* = 0.06, 95% CI [0.002, 0.11]). On trials with identical stimuli the reduction was similar in size but uncertain on its own (*b* = −0.11, 95% CI [−0.24, 0.009]). Pupil size during the grip did not differ reliably between physical effort levels. The pupil response after the stimulus to be judged was smaller under high physical effort, but the grip was released during that interval. A larger pupil just before the stimulus was weakly associated with lower sensitivity, and no pupil measure tracked the rate of "different" responses.\n\nIn Chapter 4, a hierarchical Bayesian drift-diffusion model of the same older adults\' choices and response times placed the effect of physical effort in the drift criterion. High physical effort shifted drift toward "same" on every trial (β = −0.053, 95% CrI [−0.103, −0.003]), whereas the effect on evidence quality was close to zero, the change in boundary separation was practically negligible, and the starting point did not change. Physical effort lowered drift slightly more on Hard than on Easy trials, but a model with that interaction did not predict better than a model without it. The criterion shift was small: it was clearer in the auditory task, and its interval included zero when participants with near-chance accuracy were excluded. Trial-wise pupil responses during the decision accompanied wider boundaries, but that association tracked decision duration, and no pupil measure taken before the decision predicted boundary separation or the starting point.\n\n## Integration\n\nThe three studies give a consistent answer to the resource question. In neither age group did physical effort impose a cost that grew substantially with task difficulty. In younger adults, the interaction was absent across three tasks and two behavioral measures. In older adults, the psychometric and diffusion-model analyses both allowed at most a small additional cost on the hardest discriminations. That cost was uncertain in both analyses, and treating it as a test of the capacity account was added after the Chapter 3 results were known. At 40% of MVC, holding a grip did not appreciably take away the resources needed to remember or compare stimuli.\n\nThe studies differ in what physical effort did to the judgment. In younger adults, high physical effort left accuracy unchanged and slowed responses in one task. In older adults, it changed choices: participants reported a difference less often. The psychometric analysis showed that this reduction did not come from lower sensitivity, and the diffusion model located it in the drift criterion rather than in evidence quality, response caution, or the starting point. These two analyses used the same trials, so their agreement shows that the conclusion does not depend on the model used, not that it replicates. Both also share the same weak point: the reduction on trials with identical stimuli, which distinguishes a criterion shift most directly, had the predicted direction and size but was uncertain on its own. The criterion reading is therefore the best-supported interpretation of a small effect, and it is consistent with the higher thresholds and unchanged slopes that @sun2026handgrip found in per-participant psychometric functions of the same cohort.\n\nWhether this contrast reflects age cannot be settled from these data. The younger and older samples were tested in different settings, with different stimulus differences, trial timing, and pupil measures, and Chapter 2 did not estimate a criterion. Younger adults may therefore also have shifted their criterion under high physical effort in a way that accuracy and response time did not reveal.\n\nThe pupil results follow a similar pattern. In younger adults, high physical effort enlarged the pupil response robustly in every task. In older adults, its effect during the grip was weak and reliable only in the auditory task, and the smaller pupil response after the stimulus coincided with grip release and with a higher pupil size before the stimulus. In both age groups, the pupil registered physical effort to some degree but did not account for its behavioral effects: pupil and behavioral effects were not correlated across younger adults, and in older adults no pupil measure taken before the decision predicted the criterion, the boundary, or the starting point.\n\n## Theoretical implications\n\nA single limited-capacity resource shared by force production and stimulus comparison [@Kahneman1973-jw] predicts interactions that these studies did not find in younger adults and found to be at most small in older adults. The results fit better with multiple-resource accounts, in which producing force and comparing stimuli draw on largely separate resources [@Navon1979-jk; @Wickens2008-pj]. This conclusion is limited to the force levels and tasks studied here; heavier or more prolonged physical effort could still compete with judgments.\n\nIn older adults, the main effect of physical effort was on the decision policy rather than on the evidence. This finding adds to evidence that physical exertion can change decisions that do not depend on motor performance [@Blain2019-qk], and to accounts in which the costs of physical and cognitive effort are weighed by partly shared mechanisms [@Chong2017-fx]. It is also notable for aging research. Age-related caution usually appears as wider boundaries [@ratcliff2001aging; @Starns2010-iu], yet under high physical effort the older adults here kept their boundaries essentially unchanged and shifted the criterion instead. Signal detection and diffusion-model analyses can therefore separate effects of physical effort that accuracy alone would attribute to a loss of capacity: in Chapter 4, the accuracy cost on hard trials arose mainly from the criterion shift, not from a loss of evidence quality.\n\nAdaptive gain theory links pupil size to locus coeruleus–noradrenaline activity [@Aston-Jones2005-dg], and isometric handgrip engages that system [@Mather2020-ze]. Because aging may shift the optimum of the inverted-U relation between arousal and performance to lower levels [@Mather2016-bx], the theory allowed that a 40% grip would push older adults past their optimum and degrade performance. That did not occur as a loss of sensitivity or evidence quality, and these studies do not support the stronger claim that pupil-linked processes carry the behavioral effects of physical effort. They also suggest that the pupil is a less sensitive index of physical effort in older adults, at least in a scanner, where luminance, posture, and noise are constrained. Because pupil size also covaries with activity outside the locus coeruleus [@Joshi2016-zb], links between these results and the noradrenergic system remain interpretive.\n\n## Limitations\n\nSeveral limitations cut across the chapters. First, age was compared across studies, not within one, so no difference between the younger and older adults can be attributed to age. Second, every study used only two levels of physical effort, so none could describe a dose–response relation or test an inverted-U relation between physical effort and performance. Third, in the older cohort, "different" was always reported with the right index finger and "same" with the right middle finger while the left hand held the grip, so a bias acting on the evidence for one response cannot be separated from the finger that gave it. Fourth, the trial sequence constrained the pupil measures: grip release fell inside the window after the stimulus, the window just before it contained the pupil response to the standard, and the delayed-response design limited how much response times could constrain the diffusion model. Fifth, the effects in older adults were small, and the criterion shift lost its credibility in some subsamples. Finally, Chapters 3 and 4 analyzed the same trials, so their agreement is convergence across models rather than independent replication.\n\n## Future directions\n\nThese findings motivate four lines of work. A direct comparison of younger and older adults, tested in the same setting with the same stimuli, would show whether the criterion shift is specific to aging. More than two levels of physical effort would describe how the effects scale with force and whether heavier effort produces the interaction absent here. Counterbalancing the response mapping, and using a free-response version of the task with across-trial variability in the diffusion model [@ratcliff2002estimating], would separate a criterion shift from a bias tied to one finger and constrain the boundary more directly. Finally, pupil windows that are free of preceding stimuli and end before the response, together with the locus coeruleus imaging collected during these sessions but not analyzed here, would test more directly whether the noradrenergic system links physical effort to decision policy.\n\n## Closing\n\nHolding a moderately effortful grip did not drain the resources needed to remember or discriminate stimuli in younger adults, and it drained them at most slightly in older adults. What changed in older adults was how readily they reported a difference. Physical effort may thus shape everyday judgments in later life less by degrading what is perceived than by changing the evidence required before a change is reported, a cost that falls on the small differences that are hardest to detect.\n'


class Fail(Exception):
    pass


def need(cond, msg):
    if not cond:
        raise Fail(msg)


def read(p):
    with open(os.path.join(ROOT, p), encoding="utf-8") as f:
        return f.read()


def main():
    check = "--check" in sys.argv[1:]
    for p in ("index.qmd", "references.bib", "Chapter_1_General_Introduction.qmd",
              "Chapter_5_General_Conclusion.qmd", "_quarto.yml"):
        need(os.path.isfile(os.path.join(ROOT, p)), f"not found: {p} (run from the dissertation repo root)")

    idx = read("index.qmd")
    need(idx.count("\\begin{ucrabstract}") == 1 and idx.count("\\end{ucrabstract}") == 1,
         "index.qmd must contain exactly one ucrabstract environment")
    a = idx.index("\\begin{ucrabstract}") + len("\\begin{ucrabstract}")
    b = idx.index("\\end{ucrabstract}")
    new_idx = idx[:a] + "\n" + ABSTRACT.strip() + "\n" + idx[b:]

    for name, old, head in (("Chapter_1_General_Introduction.qmd", read("Chapter_1_General_Introduction.qmd"), "# General Introduction {#sec-general-introduction}"),
                            ("Chapter_5_General_Conclusion.qmd", read("Chapter_5_General_Conclusion.qmd"), "# General Conclusion {#sec-general-conclusion}")):
        need(old.lstrip().startswith(head), f"{name}: unexpected first line (expected '{head}')")

    words = len(ABSTRACT.split())
    need(words <= 350, f"abstract has {words} words (UCR limit 350)")

    bib = read("references.bib")
    keys = set(re.findall(r"^@\w+\{([^,\s]+),", bib, re.M))
    cited = set(re.findall(r"@([A-Za-z][A-Za-z0-9_-]*[A-Za-z0-9])", CH1 + CH5))
    cited = {k for k in cited if not k.startswith(("sec-", "fig-", "tbl-"))}
    missing = sorted(cited - keys)
    need(not missing, "citation keys not in references.bib: " + ", ".join(missing))

    for name, t in (("abstract", ABSTRACT), ("Chapter 1", CH1), ("Chapter 5", CH5)):
        need("Total AUC" not in t, f"{name} contains 'Total AUC'")
    need(len(re.findall(r"^## ", CH1, re.M)) == 4, "Chapter 1 should have 4 sections")
    need(len(re.findall(r"^## ", CH5, re.M)) == 6, "Chapter 5 should have 6 sections")
    need(not re.search(r"^### ", CH1 + CH5, re.M), "unexpected sub-sections")

    out = {"index.qmd": new_idx, "Chapter_1_General_Introduction.qmd": CH1,
           "Chapter_5_General_Conclusion.qmd": CH5}
    changed = [p for p, t in out.items() if read(p) != t]
    if check:
        print(f"CHECK OK: abstract {words} words; {len(cited)} citation keys all in references.bib; "
              f"would change: {', '.join(changed) or 'nothing'}. Nothing written.")
        return
    for p, t in out.items():
        with open(os.path.join(ROOT, p), "w", encoding="utf-8") as f:
            f.write(t)
    print(f"PLACE OK: abstract {words} words; {len(cited)} citation keys all in references.bib; "
          f"changed: {', '.join(changed) or 'nothing'}.")


if __name__ == "__main__":
    try:
        main()
    except Fail as e:
        print("PLACE FAILED:", e)
        sys.exit(1)
